validator:
function validate(input) {
  const [{ Employees = [] }] = input;
  const ids = new Set();
  for (const [id, salary, dept] of Employees) {
    if (id === null || salary === null || dept === null) return 'Employees rows may not contain null.';
    if (ids.has(id)) return `emp_id ${id} appears twice.`;
    ids.add(id);
    if (salary < 0) return `Employee ${id} has a negative salary.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  const shuffle = (list) => {
    for (let i = list.length - 1; i > 0; i--) {
      const j = pick(i + 1);
      [list[i], list[j]] = [list[j], list[i]];
    }
    return list;
  };
  const Employees = [];
  if (size === 'small') {
    const depts = ['Sales', 'IT', 'HR', 'Marketing'];
    const salaries = [50000, 55000, 65000, 70000, 80000, 90000];
    const count = pick(9);
    const ids = shuffle(Array.from({ length: 20 }, (_, i) => i + 1)).slice(0, count);
    // Mostly one or two departments, so second-highest salaries and ties appear.
    const used = depts.slice(0, 1 + pick(depts.length));
    for (const id of ids) {
      const dept = used[pick(used.length)];
      Employees.push([id, salaries[pick(salaries.length)], dept]);
    }
    return [{ Employees }];
  }
  const ids = shuffle(Array.from({ length: 2000 }, (_, i) => i + 1));
  for (const id of ids) {
    Employees.push([id, 40000 + 1000 * pick(20), `Dept ${pick(50) + 1}`]);
  }
  return [{ Employees }];
}
